From 9b55006d92e5a5773dcb311ddc1fbc72c4f53b70 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 20:26:26 +0100
Subject: [PATCH] containments/desktop: allow any icon size and label width

Icon size and label width could only be set in fixed steps. The icon
size and label width settings are now sliders in pixels that can take
any value, while the context menu keeps offering the preset sizes.

BUG: 518888
---
 .../desktop/package/contents/config/main.xml  |  8 +++
 .../package/contents/ui/ConfigIcons.qml       | 60 +++++++++++++++----
 .../contents/ui/FolderItemActionButton.qml    | 19 +++---
 .../package/contents/ui/FolderView.qml        |  4 +-
 .../package/contents/ui/FolderViewLayer.qml   | 18 +++++-
 .../package/contents/ui/code/FolderTools.js   |  8 +++
 .../plugins/folder/viewpropertiesmenu.cpp     |  4 +-
 7 files changed, 96 insertions(+), 25 deletions(-)

diff --git a/containments/desktop/package/contents/config/main.xml b/containments/desktop/package/contents/config/main.xml
index 2621cac672..39db928d73 100644
--- a/containments/desktop/package/contents/config/main.xml
+++ b/containments/desktop/package/contents/config/main.xml
@@ -106,10 +106,18 @@
       <label>The icon size to use for Folder View icons. 0 = 22px (smallMedium); 1 = 32px (medium); 2 = 48px (large); 3 = 64px (huge); 4 = 96px (large * 2); 5 = 128px (enormous); 6 = 160px (medium * 5); 7 = 192px (huge * 3); 8 = 224px (medium * 7); 9 = 256px (enormous * 2)</label>
       <default>3</default>
     </entry>
+    <entry name="iconSizePixels" type="Int">
+      <label>The icon size in pixels to use for Folder View icons. 0 = use the iconSize step instead.</label>
+      <default>0</default>
+    </entry>
     <entry name="labelWidth" type="Int">
       <label>The width of the grid cells when using icon view. 0 = Narrow, 1 = Medium, 2 = Wide</label>
       <default>1</default>
     </entry>
+    <entry name="labelWidthPixels" type="Int">
+      <label>The width in pixels of the grid cells when using icon view. 0 = use the labelWidth step instead.</label>
+      <default>0</default>
+    </entry>
     <entry name="textLines" type="Int">
       <label>The (maximum) number of lines of text to use below Folder View icons.</label>
       <default>2</default>
diff --git a/containments/desktop/package/contents/ui/ConfigIcons.qml b/containments/desktop/package/contents/ui/ConfigIcons.qml
index 24c55a915c..55753811ca 100644
--- a/containments/desktop/package/contents/ui/ConfigIcons.qml
+++ b/containments/desktop/package/contents/ui/ConfigIcons.qml
@@ -18,6 +18,8 @@ import org.kde.kirigami as Kirigami
 import org.kde.kcmutils as KCM
 import org.kde.private.desktopcontainment.folder as Folder

+import "code/FolderTools.js" as FolderTools
+
 KCM.SimpleKCM {
     id: configIcons

@@ -40,8 +42,10 @@ KCM.SimpleKCM {
     property alias cfg_previews: previews.checked
     property var cfg_previewPlugins
     property alias cfg_viewMode: viewMode.currentIndex
-    property alias cfg_iconSize: iconSize.value
-    property alias cfg_labelWidth: labelWidth.currentIndex
+    property int cfg_iconSize
+    property int cfg_iconSizePixels
+    property int cfg_labelWidth
+    property int cfg_labelWidthPixels
     property alias cfg_textLines: textLines.value
     property bool cfg_useTypeAhead: Plasmoid.configuration.useTypeAhead

@@ -244,10 +248,19 @@ KCM.SimpleKCM {

             Kirigami.FormData.label: i18nc("@label:slider", "Icon size:")

-            from: 0
-            to: 9
+            from: FolderTools.iconSizes[0]
+            to: FolderTools.iconSizes[FolderTools.iconSizes.length - 1]
             stepSize: 1
             snapMode: Slider.SnapAlways
+            Kirigami.StyleHints.tickMarkStepSize: -1
+            value: FolderTools.effectiveIconSize({
+                iconSize: configIcons.cfg_iconSize,
+                iconSizePixels: configIcons.cfg_iconSizePixels,
+            })
+            onMoved: configIcons.cfg_iconSizePixels = value
+
+            ToolTip.text: i18nc("@info:tooltip %1 is a size in pixels", "%1 px", value)
+            ToolTip.visible: hovered || pressed
         }

         RowLayout {
@@ -270,18 +283,43 @@ KCM.SimpleKCM {
             }
         }

-        ComboBox {
+        Slider {
             id: labelWidth
             visible: !configIcons.inPanel || viewMode.currentIndex === 1 /* Icons mode */
             Layout.fillWidth: true

-            Kirigami.FormData.label: i18nc("@label:listbox", "Label width:")
+            Kirigami.FormData.label: i18nc("@label:slider", "Label width:")

-            model: [
-                i18nc("@item:inlistbox how long a text label should be", "Narrow"),
-                i18nc("@item:inlistbox how long a text label should be", "Medium"),
-                i18nc("@item:inlistbox how long a text label should be", "Wide"),
-            ]
+            from: Kirigami.Units.iconSizes.small * 4
+            to: Kirigami.Units.iconSizes.small * 16
+            stepSize: 1
+            snapMode: Slider.SnapAlways
+            Kirigami.StyleHints.tickMarkStepSize: -1
+            value: FolderTools.effectiveLabelWidth({
+                labelWidth: configIcons.cfg_labelWidth,
+                labelWidthPixels: configIcons.cfg_labelWidthPixels,
+            })
+            onMoved: configIcons.cfg_labelWidthPixels = value
+
+            ToolTip.text: i18nc("@info:tooltip %1 is a size in pixels", "%1 px", value)
+            ToolTip.visible: hovered || pressed
+        }
+
+        RowLayout {
+            Layout.fillWidth: true
+            visible: labelWidth.visible
+
+            Label {
+                Layout.alignment: Qt.AlignLeft
+                text: i18nc("@item:inrange how long a text label should be", "Narrow")
+            }
+            Item {
+                Layout.fillWidth: true
+            }
+            Label {
+                Layout.alignment: Qt.AlignRight
+                text: i18nc("@item:inrange how long a text label should be", "Wide")
+            }
         }

         SpinBox {
diff --git a/containments/desktop/package/contents/ui/FolderItemActionButton.qml b/containments/desktop/package/contents/ui/FolderItemActionButton.qml
index 6f7aa24e44..fbee984f60 100644
--- a/containments/desktop/package/contents/ui/FolderItemActionButton.qml
+++ b/containments/desktop/package/contents/ui/FolderItemActionButton.qml
@@ -10,6 +10,8 @@ import org.kde.plasma.plasmoid
 import org.kde.kirigami as Kirigami
 import org.kde.ksvg as KSvg

+import "code/FolderTools.js" as FolderTools
+
 KSvg.SvgItem {
     id: actionButton

@@ -17,16 +19,15 @@ KSvg.SvgItem {
         if (!visible) {
             return 0;
         }
-        switch (Plasmoid.configuration.iconSize) {
-            case 0: return Kirigami.Units.iconSizes.small;
-            case 1: return Kirigami.Units.iconSizes.small;
-            case 2: return Kirigami.Units.iconSizes.smallMedium;
-            case 3: return Kirigami.Units.iconSizes.smallMedium;
-            case 4: return Kirigami.Units.iconSizes.smallMedium;
-            case 5: return Kirigami.Units.iconSizes.medium;
-            case 6: return Kirigami.Units.iconSizes.large;
-            default: return Kirigami.Units.iconSizes.small;
+        const iconSize = FolderTools.effectiveIconSize(Plasmoid.configuration);
+        if (iconSize <= Kirigami.Units.iconSizes.medium) {
+            return Kirigami.Units.iconSizes.small;
+        } else if (iconSize <= Kirigami.Units.iconSizes.large * 2) {
+            return Kirigami.Units.iconSizes.smallMedium;
+        } else if (iconSize <= Kirigami.Units.iconSizes.enormous) {
+            return Kirigami.Units.iconSizes.medium;
         }
+        return Kirigami.Units.iconSizes.large;
     }
     height: width

diff --git a/containments/desktop/package/contents/ui/FolderView.qml b/containments/desktop/package/contents/ui/FolderView.qml
