 import org.kde.private.desktopcontainment.folder as Folder

+import "code/FolderTools.js" as FolderTools
+
 FocusScope {
     id: folderViewLayerComponent

@@ -65,6 +67,13 @@ FocusScope {
         }
     }

+    function iconSizeMenuIndex(): int {
+        if (Plasmoid.configuration.iconSizePixels) {
+            return FolderTools.iconSizes.indexOf(Plasmoid.configuration.iconSizePixels);
+        }
+        return Plasmoid.configuration.iconSize;
+    }
+
     Binding {
         target: Plasmoid
         property: "title"
@@ -122,6 +131,7 @@ FocusScope {

         onIconSizeChanged: {
             Plasmoid.configuration.iconSize = iconSize;
+            Plasmoid.configuration.iconSizePixels = 0;
         }

         Component.onCompleted: {
@@ -132,7 +142,7 @@ FocusScope {
             sortMode = Plasmoid.configuration.sortMode;
             sortDesc = Plasmoid.configuration.sortDesc;
             sortDirsFirst = Plasmoid.configuration.sortDirsFirst;
-            iconSize = Plasmoid.configuration.iconSize;
+            iconSize = folderViewLayerComponent.iconSizeMenuIndex();
         }
     }

@@ -196,7 +206,11 @@ FocusScope {
         }

         function onIconSizeChanged() {
-            viewPropertiesMenu.iconSize = Plasmoid.configuration.iconSize;
+            viewPropertiesMenu.iconSize = folderViewLayerComponent.iconSizeMenuIndex();
+        }
+
+        function onIconSizePixelsChanged() {
+            viewPropertiesMenu.iconSize = folderViewLayerComponent.iconSizeMenuIndex();
         }
     }

diff --git a/containments/desktop/package/contents/ui/code/FolderTools.js b/containments/desktop/package/contents/ui/code/FolderTools.js
index 449b386da8..0f6b5d9a67 100644
--- a/containments/desktop/package/contents/ui/code/FolderTools.js
+++ b/containments/desktop/package/contents/ui/code/FolderTools.js
@@ -19,6 +19,14 @@ function iconSizeFromTheme(size) {
     return iconSizes[size];
 }

+function effectiveIconSize(configuration) {
+    return configuration.iconSizePixels || iconSizeFromTheme(configuration.iconSize);
+}
+
+function effectiveLabelWidth(configuration) {
+    return configuration.labelWidthPixels || Kirigami.Units.iconSizes.small * ((configuration.labelWidth * 2) + 4);
+}
+
 function effectiveNavDirection(flow, layoutDirection, direction) {
     if (direction == Qt.LeftArrow) {
         if (flow == GridView.FlowLeftToRight) {
