@@ -273,7 +273,7 @@ void ViewPropertiesMenu::setSortDirsFirst(bool sortDirsFirst)

 int ViewPropertiesMenu::iconSize() const
 {
-    return m_iconSize->checkedAction()->data().toInt();
+    return m_iconSize->checkedAction() ? m_iconSize->checkedAction()->data().toInt() : -1;
 }

